import React from 'react';

import { formatAltitude, formatDistance } from '@helpers/formatHelper';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { getLeafletMapManager } from '../../../@managers/leafletMap.manager';
import { useRoutesSelector } from '../../../@store/hooks';
import {
  IBaseRouteObjectLine,
  IBaseRouteObjectPoint,
  RouteObjectType,
} from '../../../@types/routes.types';
import ElevationChart from '../Elevation/ElevationChart';
import Summary from '../Summary';

const RoutesEditorFooter: React.FC = () => {
  const [mode, setMode] = React.useState<'default' | 'all' | 'all_in_distance'>('default');

  const { routeInfo, activeRouteObject, routeObjects, currentRouteObject, newRouteObject } =
    useRoutesSelector((state) => state.route);

  const obj = newRouteObject ?? currentRouteObject ?? activeRouteObject;

  if (!routeInfo) return null;

  if (
    newRouteObject &&
    newRouteObject.type === RouteObjectType.Line &&
    !newRouteObject.points.length
  )
    return <div>Добавьте точки </div>;

  if (obj && obj.type === RouteObjectType.Line && obj.points.length) {
    let points: [number, number, number][] = obj.points as [number, number, number][];

    if (mode !== 'default') {
      points = [];
      (
        routeObjects.filter(
          (r) => r.type === RouteObjectType.Line && (mode === 'all' || r.is_in_distance),
        ) as IBaseRouteObjectLine[]
      )
        .toSorted((a, b) => a.order - b.order)
        .forEach((ro) => {
          points.push(...(ro.points as [number, number, number][]));
        });
    }

    return (
      <footer
        style={{ color: obj.color ?? '#333' }}
        key={mode}
        onDoubleClick={(e) => {
          if (e.shiftKey)
            return setMode((cur) => (cur === 'default' ? 'all_in_distance' : 'default'));
          return setMode((cur) => (cur === 'default' ? 'all' : 'default'));
        }}
      >
        <PohRow>
          <PohCol sm={1}>
            <Summary points={points} />
          </PohCol>
          <PohCol sm={11}>
            <ElevationChart
              points={points}
              poi={
                routeObjects.filter(
                  (ro) => ro.type === RouteObjectType.Point,
                ) as IBaseRouteObjectPoint[]
              }
              onCursorMove={(point, re) => {
                getLeafletMapManager().setHighlightedPointCoordinates(
                  point,
                  formatAltitude(point[2]) + '\n' + formatDistance(re),
                );
              }}
              onEndCursorMove={() => {
                getLeafletMapManager().clearHighlightedPoint();
              }}
              onStartCursorMove={() => {}}
            />
          </PohCol>
        </PohRow>
      </footer>
    );
  }

  return null;
};

export default RoutesEditorFooter;
