import React from 'react';

import { Provider } from 'react-redux';

import { routesStore } from '../@store/store';
import RoutesEditorWrapper from './components/RoutesEditorWrapper/RoutesEditorWrapper';

interface IRouteEditorProps {
  id?: number;
  search?: any;
}

const RouteEditorNew: React.FC<IRouteEditorProps> = ({ id }) => {
  return (
    <Provider store={routesStore}>
      <RoutesEditorWrapper id={id} />
    </Provider>
  );
};

export default RouteEditorNew;
