import React from 'react';

import ChevronBarLeft from '@pohodnik/icons/svg/Chevrons/ChevronBarLeft';
import GeoAltFill from '@pohodnik/icons/svg/Geo/GeoAltFill';
import Bezier2 from '@pohodnik/icons/svg/Graphics/Bezier2';
import L from 'leaflet';
import { useMap } from 'react-leaflet';

import PohButton, { ButtonVariant } from '@ui-kit/Button';

import { getLeafletMapManager } from '../../../../@managers/leafletMap.manager';
import { useRoutesDispatch, useRoutesSelector } from '../../../../@store/hooks';
import { toggleSidebar } from '../../../../@store/route.slice';
import { getPointAround } from '../../PointsAround';

const POSITION_CLASSES = {
  bottomleft: 'leaflet-bottom leaflet-left',
  bottomright: 'leaflet-bottom leaflet-right',
  topleft: 'leaflet-top leaflet-left',
  topright: 'leaflet-top leaflet-right',
};

interface IControlEditorProps {
  position: keyof typeof POSITION_CLASSES;
}

const ControlEditor: React.FC<IControlEditorProps> = ({ position }) => {
  const { isSidebarCollapsed } = useRoutesSelector((s) => s.route);
  const map = useMap();
  const dispatch = useRoutesDispatch();
  const positionClass = (position && POSITION_CLASSES[position]) || POSITION_CLASSES.topright;
  return (
    <>
      <div className={positionClass} style={{ boxShadow: 'none' }}>
        <div className="leaflet-control leaflet-bar" style={{ boxShadow: 'none', border: 'none' }}>
          <PohButton
            icon={true}
            variant={ButtonVariant.Light}
            onClick={() => getLeafletMapManager().startNewLine()}
            className="shadow me-1"
            title="Нарисовать трек"
          >
            <Bezier2 />
          </PohButton>
          <PohButton
            icon={true}
            onClick={async (e) => {
              let latLng: L.LatLng | undefined;
              let name: string | undefined;

              if (e.ctrlKey || e.shiftKey) {
                const center = map.getCenter();
                const po = await getPointAround(center.lat, center.lng);
                if (po) {
                  latLng = new L.LatLng(po.lat, po.lon);
                  name = po.name;
                }
              }

              getLeafletMapManager().startNewPoint(latLng, name);
            }}
            className="shadow"
            title="Нарисовать точку"
          >
            <GeoAltFill />
          </PohButton>

          {isSidebarCollapsed && (
            <PohButton className="ms-4" icon={true} onClick={() => dispatch(toggleSidebar())}>
              <ChevronBarLeft />
            </PohButton>
          )}
        </div>
      </div>
    </>
  );
};

export default ControlEditor;
