import React from 'react';

import clsx from 'clsx';

import PohAlert from '@ui-kit/Alert';
import PohLoader from '@ui-kit/Loader';

import styles from './styles.module.less';
import { useRoutesDispatch, useRoutesSelector } from '../../../@store/hooks';
import { getRouteBaseData } from '../../../@store/route.thunk';
import RouteEditorMap from '../RouteEditorMap';
import RoutesEditorFooter from '../RoutesEditorFooter/RoutesEditorFooter';
import RoutesEditorHeader from '../RoutesEditorHeader/RoutesEditorHeader';
import RoutesEditorSidebar from '../RoutesEditorSidebar/RoutesEditorSidebar';

interface IRoutesEditorWrapperProps {
  id?: number;
}

const RoutesEditorWrapper: React.FC<IRoutesEditorWrapperProps> = ({ id }) => {
  const dispatch = useRoutesDispatch();

  const { isBaseInfoLoading, baseInfoError, routeInfo } = useRoutesSelector((state) => state.route);

  React.useEffect(() => {
    if (id) dispatch(getRouteBaseData(id));
  }, [id]);

  if (isBaseInfoLoading) {
    return (
      <div className="d-flex justify-content-center align-items-center">
        <PohLoader />
      </div>
    );
  }
  if (baseInfoError) {
    return (
      <div>
        <PohAlert>{baseInfoError.message}</PohAlert>
      </div>
    );
  }

  if (!routeInfo?.id) {
    return (
      <div>
        <PohAlert>Has no riuteInfo</PohAlert>
      </div>
    );
  }

  return (
    <section className={clsx(styles.routeEditor)}>
      <RoutesEditorHeader />
      <main>
        <div className={styles.mapContainer}>
          <RouteEditorMap />
        </div>
        <RoutesEditorSidebar />
      </main>
      <RoutesEditorFooter />
    </section>
  );
};

export default RoutesEditorWrapper;
