/* eslint-disable @typescript-eslint/ban-ts-comment */
/* eslint-disable no-console */
/* eslint-disable import/order */
import * as L from 'leaflet';

import {
  getCoordsFromLatLng,
  setMarkerObstacle,
  setPolylineText,
} from './../@helpers/leaflet.helper';
import 'leaflet-textpath';
import { formatDistance } from '@helpers/formatHelper';
import { success } from '@helpers/notificationHelper';
import { XneekLoader } from '../@classes/XneekLoader/XneekLoader';
import {
  getXneekPointEditorSingletone,
  IXneekPointEditorOptions,
  XneekPointEditor,
} from '../@classes/XneekPointEditor/XneekPointEditor';
import {
  getXneekPolylineEditorSingletone,
  XneekPolylineEditor,
} from '../@classes/XneekPolylineEditor/XneekPolylineEditor';
import {
  DEFAULT_LINE_COLOR,
  DEFAULT_LINE_OPACITY,
  DEFAULT_LINE_WEIGHT,
  DEFAULT_POINT_COLOR,
  TEMPORARY_LINE_DASH_ARRAY,
  TEMPORARY_POINT_OPACITY,
} from '../@const/routeObjects.const';
import {
  applyMarkerActive,
  applyPolylineActive,
  getDivIcon,
  getHighlightedPointIcon,
  getMarkerStyles,
  IMarkerStyles,
  setMarkerStyles,
} from '../@helpers/leaflet.helper';

import crEl from 'xneek-crel';

import { CoordsWithOptionalEle, getCoordsWithElevationsAsync } from '../@services/routes.service';
import { IRouteObject, RouteObjectType } from '../@types/routes.types';
import { getPointAround } from '../RouteEditorNew/components/PointsAround';
class LeafletMapManager {
  private map: L.Map;

  private lineEditor: XneekPolylineEditor;
  private pointEditor: XneekPointEditor;

  private addStartCallback: () => void;
  private editStartCallback: (id: IRouteObject['id'], e: L.Layer) => void;
  private onSelectRouteObject: (id?: IRouteObject['id'] | null, e?: L.Layer) => void;
  private onHotChange: (
    coordinates: CoordsWithOptionalEle[],
    activeLayerId: IRouteObject['id'] | null,
  ) => void;
  private onAddCallback: (e: L.Layer, cb: (e: IRouteObject) => void, name?: string) => void;

  private pointsLayers: Record<IRouteObject['id'], L.Marker> = {};
  private linesLayers: Record<IRouteObject['id'], L.Polyline> = {};

  private editingLayerId: IRouteObject['id'] | null = null;
  private activeLayerId: IRouteObject['id'] | null = null;

  private formElement: HTMLFormElement | null = null;

  private highlightedPoint: L.Marker | null = null;
  private highlightedPointTimer: ReturnType<typeof setTimeout> | null = null;

  private loader = new XneekLoader();

  public hasCoordinatesChanges: boolean = false;

  private backupPolyline: L.LatLng[] | L.LatLng[][] | L.LatLng[][][] | undefined = undefined;
  private backupPoint: L.LatLng | undefined = undefined;

  private markerStyles: IMarkerStyles | undefined = undefined;
  private backupMarkerStyles: IMarkerStyles | undefined = undefined;

  constructor(
    map: L.Map,
    onAddCallback: (e: L.Layer, cb: (e: IRouteObject) => void, name?: string) => void,
    onEditStarted: (id: IRouteObject['id'], e: L.Layer) => void,
    onSelectRouteObject: (id?: IRouteObject['id'] | null, e?: L.Layer) => void,
    onHotChange: (
      coordinates: CoordsWithOptionalEle[],
      activeLayerId: IRouteObject['id'] | null,
    ) => void,
    addStartCallback: () => void,
  ) {
    this.map = map;
    this.lineEditor = getXneekPolylineEditorSingletone(map);
    this.pointEditor = getXneekPointEditorSingletone(map);
    this.editStartCallback = onEditStarted;
    this.onAddCallback = onAddCallback;
    this.onSelectRouteObject = onSelectRouteObject;
    this.onHotChange = onHotChange;
    this.addStartCallback = addStartCallback;

    this.lineEditor.setLineOptions({
      color: DEFAULT_LINE_COLOR,
      opacity: DEFAULT_LINE_OPACITY,
      weight: DEFAULT_LINE_WEIGHT,
    });

    this.pointEditor.setPointOptions({
      color: DEFAULT_POINT_COLOR,
    });

    this.map.on('click', async () => {
      this.inactivate();
    });
  }

  destructor() {
    this.lineEditor.destroy();
    this.pointEditor.destroy();
  }

  setMap = (mapForSet: L.Map) => {
    this.map = mapForSet;
    this.pointsLayers = {};
    this.linesLayers = {};
  };

  _editorInit(layer: L.Marker | L.Polyline, id: IRouteObject['id']) {
    layer.on('click', async (e) => {
      L.DomEvent.stopPropagation(e);
      this.makeRouteObjectActive(id);
    });

    layer.on('dblclick', async (e) => {
      L.DomEvent.stopPropagation(e);
      this.startEdit(id);
    });
    layer.on('contextmenu', async (e) => {
      L.DomEvent.stopPropagation(e);
      this.startEdit(id);
    });
  }

  private addPoint = (id: IRouteObject['id'], point: L.Marker) => {
    this._editorInit(point, id);
    this.pointsLayers[id] = point;
    this.map.addLayer(point);
  };

  private addLine = (id: IRouteObject['id'], line: L.Polyline) => {
    this._editorInit(line, id);
    this.linesLayers[id] = line;

    line.on('mouseover', function () {
      setPolylineText(line, '  ➤  ', {
        repeat: true,
        center: true,
        offset: 4,
        attributes: {
          fill: 'white',
          fontSize: (6 + +(line.options.weight || '')).toString(),
          opacity: '0.9',
        },
      });
    });

    line.on('mouseout', function () {
      setPolylineText(line, null);
    });

    this.map.addLayer(line);
  };

  addRouteObject = (routeObject: IRouteObject) => {
    if (routeObject.type === RouteObjectType.Point) {
      const marker = L.marker(routeObject.coordinates, { icon: getDivIcon() });

      this.addPoint(routeObject.id, marker);

      setMarkerStyles(marker, {
        color: routeObject.color,
        opacity: routeObject.is_in_distance ? 1 : TEMPORARY_POINT_OPACITY,
      });

      if (routeObject.obstacle) {
        setMarkerObstacle(marker, routeObject.obstacle);
      }
    } else if (routeObject.type === RouteObjectType.Line) {
      const pl = L.polyline(routeObject.points, {
        color: routeObject.color,
        weight: routeObject.width,
        opacity: routeObject.opacity / 100,
        dashArray: routeObject.is_in_distance ? undefined : TEMPORARY_LINE_DASH_ARRAY,
      });
      this.addLine(routeObject.id, pl);
    }
  };

  setCurrentId = (id: IRouteObject['id'] | null) => {
    //console.debug('setCurrent', id);
    this.editingLayerId = id;
  };
  setFormElement = (formElement: HTMLFormElement | null) => {
    // console.debug('formElement', formElement);
    this.formElement = formElement;
  };
  getCurrentId = (): IRouteObject['id'] | null => {
    return this.editingLayerId;
  };

  getPointById = (id: IRouteObject['id']): L.Marker | null => {
    return this.pointsLayers[id] || null;
  };

  getLineById = (id: IRouteObject['id']): L.Polyline | null => {
    return this.linesLayers[id] || null;
  };

  centerOnPoint(coordinates: L.LatLngExpression, maxZoom = false) {
    this.map.setView(coordinates, maxZoom ? this.map.getMaxZoom() : undefined);
  }
  fitBounds(bounds: L.LatLngBoundsExpression, options?: L.FitBoundsOptions) {
    this.map.fitBounds(bounds, options);
  }

  async startNewLine(initLatLngs: L.LatLng[] = [], name?: string) {
    this.inactivate();
    await this.completeCurrent();
    this.hasCoordinatesChanges = false;
    this.lineEditor.startEdit(initLatLngs, {
      color: DEFAULT_LINE_COLOR,
      opacity: DEFAULT_LINE_OPACITY,
      weight: DEFAULT_LINE_WEIGHT,
    });

    this.lineEditor.setAsyncPointDebounce(2000);
    this.lineEditor.setAsyncPointUpdater((points) => {
      return new Promise((resolve, reject) => {
        const coordsWithoutEle: CoordsWithOptionalEle[] = [];
        const indexesMap: Record<number, number> = {};

        points.forEach((p, i) => {
          if (!Number.isFinite(p.alt)) {
            indexesMap[i] = coordsWithoutEle.length;
            coordsWithoutEle.push(getCoordsFromLatLng(p));
          }
        });

        !coordsWithoutEle.length
          ? resolve(points)
          : getCoordsWithElevationsAsync(coordsWithoutEle)
              .then((coordsWithEle) => {
                const updatedPoints = points.map((point, i) =>
                  Number.isFinite(indexesMap[i])
                    ? new L.LatLng(...coordsWithEle[indexesMap[i]])
                    : point,
                );
                resolve(updatedPoints);
              })
              .catch(reject);
      });
    });

    this.lineEditor.onChange(({ marker, points, index, distance, reason }) => {
      console.log('new line', { marker, points, distance, index, reason });

      const newPoints = points.map(getCoordsFromLatLng);
      this.onHotChange(newPoints, this.editingLayerId);
      this.hasCoordinatesChanges = true;

      //@ts-ignore
      if (this.formElement && this.formElement.elements.distance) {
        //@ts-ignore
        this.formElement.elements.distance.value = formatDistance(distance);
      }
    });

    this.lineEditor.onSave((points) => {
      //@ts-ignore
      const tmpLine = L.polyline(points, {
        color: DEFAULT_LINE_COLOR,
        opacity: DEFAULT_LINE_OPACITY,
        weight: DEFAULT_LINE_WEIGHT,
      });
      this.map.addLayer(tmpLine);
      console.log('xneek', 'ADD TMP', tmpLine);
      this.loader.startLoadingForPolyline(tmpLine);

      this.onAddCallback(
        tmpLine,
        () => {
          this.loader.stopLoadingForPolyline(tmpLine);
          this.map.removeLayer(tmpLine);
          tmpLine.remove();
          console.log('REMOVE TMP', tmpLine);
        },
        name,
      );
    });
    this.addStartCallback();
  }

  async startNewPoint(initLatLng?: L.LatLng, name?: string) {
    this.inactivate();
    await this.completeCurrent();
    this.pointEditor.startEdit(initLatLng, { color: DEFAULT_POINT_COLOR });
    initLatLng && this.centerOnPoint(initLatLng);
    this.hasCoordinatesChanges = false;
    this.pointEditor.onChange(() => {
      this.hasCoordinatesChanges = true;
      // clearTimeout(debounceTimer);
      // debounceTimer = setTimeout(() => {
      //   getCoordsWithElevationsAsync([getCoordsFromLatLng(latlng)]).then(([coordsWithEle]) => {
      //     editorPointUpdate?.(new L.LatLng(...coordsWithEle))
      //   });
      // }, 600)
    });
    this.pointEditor.onSave((point) => {
      if (!point) return;
      const tmpPoint = L.marker(point, { icon: getDivIcon() });
      this.map.addLayer(tmpPoint);
      setMarkerStyles(tmpPoint, { color: 'violet' });
      this.loader.startLoadingForMarker(tmpPoint);

      this.onAddCallback(
        tmpPoint,
        () => {
          this.loader.stopLoadingForMarker(tmpPoint);
          this.map.removeLayer(tmpPoint);
          tmpPoint.remove();
        },
        name,
      );
    });
    this.addStartCallback();
  }

  completeCurrent() {
    if (this.editingLayerId) {
      this.formElement && this.formElement.requestSubmit();
    }

    return Promise.resolve(true);
  }

  updateCurrent(property: 'color' | 'opacity' | 'width' | 'temporary', value: any) {
    // if (this.editingLayerId==null) throw new Error(`Has no editingLayerId for updateCurrent`);
    // const layer = this.pointsLayers[this.editingLayerId] ?? this.linesLayers[this.editingLayerId];
    // if (!layer) throw new Error(`layer with id ${this.editingLayerId} not found`);

    //if (layer instanceof L.Polyline) {
    const options: L.PolylineOptions = {};

    switch (property) {
      case 'color':
        options.color = value;
        break;
      case 'opacity':
        options.opacity = value;
        break;
      case 'width':
        options.weight = value;
        break;
      case 'temporary':
        options.dashArray = value ? TEMPORARY_LINE_DASH_ARRAY : undefined;
        break;
      default:
        throw new Error(`Unknown property ${property} for updateCurrent`);
    }

    this.lineEditor.setLineOptions(options);
    // }

    //if (layer instanceof L.Marker) {
    const options2: Partial<IXneekPointEditorOptions> = {};

    switch (property) {
      case 'color':
        options2.color = value;
        break;
      case 'temporary':
        options2.opacity = value ? TEMPORARY_POINT_OPACITY : 1;
        break;
      default:
        throw new Error(`Unknown property ${property} for updateCurrent`);
    }

    this.markerStyles = options2;
    this.pointEditor.setPointOptions(options2);
    //}
  }

  async makeRouteObjectActive(id: IRouteObject['id'], makeCentred = true) {
    this.clearHighlightedPoint();
    this.activeLayerId && this.inactivate();

    const layer = this.pointsLayers[id] ?? this.linesLayers[id];
    if (!layer) throw new Error(`layer with id ${id} not found`);

    if (layer instanceof L.Marker) {
      makeCentred && this.centerOnPoint(layer.getLatLng());
      applyMarkerActive(layer);
    }

    if (layer instanceof L.Polyline) {
      applyPolylineActive(layer, true);
      makeCentred &&
        this.fitBounds(layer.getBounds(), {
          paddingBottomRight: [0, 250],
        });
    }

    this.activeLayerId = id;
    this.onSelectRouteObject(id, layer);
  }

  async inactivate() {
    const id = this.activeLayerId;
    if (!id) {
      console.warn('No layerId for activate');
      return;
    }

    const layer = this.pointsLayers[id] ?? this.linesLayers[id];
    if (!layer) throw new Error(`layer with id ${id} not found`);

    if (layer instanceof L.Marker) {
      applyMarkerActive(layer, false);
    }

    if (layer instanceof L.Polyline) {
      applyPolylineActive(layer, false);
    }

    this.activeLayerId = null;
    this.onSelectRouteObject(null, layer);
    this.clearHighlightedPoint();
  }

  async startEdit(id: IRouteObject['id']) {
    this.inactivate();
    //if (this.getCurrentId() !== id) return;
    const layer = this.pointsLayers[id] ?? this.linesLayers[id];
    if (!layer) throw new Error(`layer with id ${id} not found`);

    await this.completeCurrent();
    this.hasCoordinatesChanges = false;

    if (layer instanceof L.Polyline) {
      this.backupPolyline = layer.getLatLngs();
      this.lineEditor.destroy();
      this.lineEditor.startEdit(layer.getLatLngs() as Array<L.LatLng>, layer.options);

      this.map.removeLayer(layer);

      this.lineEditor.setAsyncPointDebounce(2000);
      this.lineEditor.setAsyncPointUpdater((points) => {
        return new Promise((resolve, reject) => {
          const coordsWithoutEle: CoordsWithOptionalEle[] = [];
          const indexesMap: Record<number, number> = {};

          points.forEach((p, i) => {
            if (!Number.isFinite(p.alt)) {
              indexesMap[i] = coordsWithoutEle.length;
              coordsWithoutEle.push(getCoordsFromLatLng(p));
            }
          });

          !coordsWithoutEle.length
            ? resolve(points)
            : getCoordsWithElevationsAsync(coordsWithoutEle)
                .then((coordsWithEle) => {
                  const updatedPoints = points.map((point, i) =>
                    Number.isFinite(indexesMap[i])
                      ? new L.LatLng(...coordsWithEle[indexesMap[i]])
                      : point,
                  );
                  resolve(updatedPoints);
                })
                .catch(reject);
        });
      });
      this.lineEditor.onChange(({ marker, points, distance, index, reason }) => {
        console.log('edit line', { marker, points, distance, index, reason });

        layer.setLatLngs(points);

        const newPoints = points.map(getCoordsFromLatLng);
        this.onHotChange(newPoints, this.editingLayerId);

        this.hasCoordinatesChanges = true;
        //@ts-ignore
        if (this.formElement && this.formElement.elements.distance) {
          //@ts-ignore
          this.formElement.elements.distance.value = formatDistance(distance);
        }
      });

      this.lineEditor.onSave((points) => {
        // Сохранение по клику вне редактируемой линии
        layer.setLatLngs(points);
        this.startLoadingForCurrent();
        this.lineEditor.destroy();
        //console.log('xneek', 'lineEditor on save add layer')
        this.map.addLayer(layer); // Линия была скрыта (удалена) при включении редактора. Теперь надо вернуть
        this.formElement && this.formElement.requestSubmit();
      });

      this.lineEditor.onPointContextmenu((e, { remove, setLatLng }) => {
        L.DomEvent.stopPropagation(e);
        const onePointContextMenu = {
          'Удалить эту точку': remove,
          'Разрезать на два в этой точке': () => {
            //@ts-ignore
            this.formElement.elements.dividePoint.value = getCoordsFromLatLng(e.latlng);
            this.formElement && this.formElement.requestSubmit();
          },
          'Удалить отсюда до конца (красная точка)': () => {
            //@ts-ignore
            this.formElement.elements.dividePoint.value = getCoordsFromLatLng(e.latlng);
            //@ts-ignore
            this.formElement.elements.operation.value = 'deleteToEnd';
            this.formElement && this.formElement.requestSubmit();
          },
          'Удалить от старта (зеленая точка) досюда': () => {
            //@ts-ignore
            this.formElement.elements.dividePoint.value = getCoordsFromLatLng(e.latlng);
            //@ts-ignore
            this.formElement.elements.operation.value = 'deleteFromStart';
            this.formElement && this.formElement.requestSubmit();
          },
          'Добавить сюда точку': async (ev: MouseEvent) => {
            ev.stopPropagation();
            this.formElement && this.formElement.reset();

            let latLng: L.LatLng | undefined = (e as any).latlng;
            let name: string | undefined;

            if (latLng && (ev.ctrlKey || ev.shiftKey)) {
              const po = await getPointAround(latLng.lat, latLng.lng);
              if (po) {
                latLng = new L.LatLng(po.lat, po.lon);
                name = po.name;
              }
            }

            getLeafletMapManager().startNewPoint(latLng, name);
          },

          'Привязать к ближайшей POI': async (ev: MouseEvent) => {
            ev.stopPropagation();
            let latLng: L.LatLng | undefined = (e as any).latlng;

            if (latLng) {
              const po = await getPointAround(latLng.lat, latLng.lng);
              if (po) {
                latLng = new L.LatLng(po.lat, po.lon);
                setLatLng(latLng);
                success(`Привязано к точке ${po.name}`);
              }
            }
          },
        };

        e.target.bindPopup(
          crEl<HTMLDivElement>(
            crEl(
              { c: 'list-group' },
              Object.entries(onePointContextMenu).map(([label, fn]) => {
                return crEl(
                  'button',
                  { c: 'list-group-item list-group-item-action', e: { click: fn } },
                  label,
                );
              }),
            ),
          ),
        );
        e.target.openPopup();
        //this.onPointContextmenuHandler(e, { remove: () => this.removeMarker(marker) })
      });
    }

    if (layer instanceof L.Marker) {
      this.backupPoint = layer.getLatLng();

      this.pointEditor.destroy();

      this.markerStyles = getMarkerStyles(layer);
      this.backupMarkerStyles = this.markerStyles;

      this.pointEditor.startEdit(layer.getLatLng(), this.markerStyles);

      this.map.removeLayer(layer);
      layer.remove();

      this.pointEditor.onChange((latlng) => {
        // Обновляем позицию маркера даже не смотря на то, что он невидим, сохранение может произойти в любой момент, нужны его реальные координаты
        layer.setLatLng(latlng);
        this.hasCoordinatesChanges = true;
        // clearTimeout(debounceTimer);
        // debounceTimer = setTimeout(() => {
        //   getCoordsWithElevationsAsync([getCoordsFromLatLng(latlng)]).then(([coordsWithEle]) => {
        //     editorPointUpdate?.(new L.LatLng(...coordsWithEle))
        //   });
        // }, 600)
      });

      this.pointEditor.onSave((point) => {
        // Сохранение по клику вне редактируемой линии
        point && layer.setLatLng(point);
        this.formElement && this.formElement.requestSubmit();
      });
    }

    layer instanceof L.Marker && this.centerOnPoint(layer.getLatLng());

    // layer instanceof L.Polyline && this.fitBounds(layer.getBounds(), {
    //     paddingBottomRight: [0, 250]
    //   });

    this.editStartCallback(id, layer);
    this.setCurrentId(id);
  }

  completeEdit(id: IRouteObject['id'], needResetCurrent = true) {
    const layer = this.pointsLayers[id] ?? this.linesLayers[id];
    if (!layer) throw new Error(`layer with id ${id} not found (completeEdit)`);

    if (layer instanceof L.Marker) {
      this.backupPoint = undefined;
      this.pointEditor.destroy();

      this.map.addLayer(layer); // Линия была скрыта (удалена) при включении редактора. Теперь надо вернуть
      this.markerStyles && setMarkerStyles(layer, this.markerStyles);

      this.markerStyles = undefined;
      this.backupMarkerStyles = undefined;
    }

    if (layer instanceof L.Polyline) {
      this.backupPolyline = undefined;
      this.lineEditor.destroy();
      console.log('xneek', 'complete edit add layer');

      this.map.removeLayer(layer); // Линия была скрыта (удалена) при включении редактора. Теперь надо вернуть
    }

    needResetCurrent && this.setCurrentId(null);
  }

  cancelEdit(id: IRouteObject['id']) {
    const layer = this.pointsLayers[id] ?? this.linesLayers[id];
    if (!layer) throw new Error(`layer with id ${id} not found (cancelEdit)`);

    if (layer instanceof L.Marker) {
      this.pointEditor.destroy();
      this.backupPoint && layer.setLatLng(this.backupPoint);
      this.map.addLayer(layer); // Линия была скрыта (удалена) при включении редактора. Теперь надо вернуть
      this.backupPoint = undefined;

      this.backupMarkerStyles && setMarkerStyles(layer, this.backupMarkerStyles);
      this.backupMarkerStyles = undefined;
    }

    if (layer instanceof L.Polyline) {
      this.lineEditor.destroy();
      this.backupPolyline && layer.setLatLngs(this.backupPolyline);
      console.log('xneek', 'cancel edit add layer');
      //this.map.addLayer(layer); // Линия была скрыта (удалена) при включении редактора. Теперь надо вернуть
      this.backupPolyline = undefined;
    }
    this.markerStyles = undefined;
    this.setCurrentId(null);
  }

  setHighlightedPointCoordinates(coords: L.LatLngExpression, caption = 'ТУТА') {
    this.highlightedPointTimer && clearTimeout(this.highlightedPointTimer);
    if (!this.highlightedPoint) {
      this.highlightedPoint = L.marker(coords, { icon: getHighlightedPointIcon(caption) }).addTo(
        this.map,
      );
    }

    this.highlightedPoint.setLatLng(coords);
    this.highlightedPoint.setIcon(getHighlightedPointIcon(caption));
  }
  clearHighlightedPoint() {
    this.highlightedPointTimer && clearTimeout(this.highlightedPointTimer);
    if (this.highlightedPoint) {
      this.highlightedPointTimer = setTimeout(() => {
        if (this.highlightedPoint) {
          this.map.removeLayer(this.highlightedPoint);
          this.highlightedPoint = null;
        }
      }, 1000);

      if (this.highlightedPoint) {
        this.map.removeLayer(this.highlightedPoint);
        this.highlightedPoint = null;
      }
    }
  }

  reset = () => {
    this.pointsLayers = {};
    this.linesLayers = {};
  };

  startLoadingForCurrent() {
    if (!this.editingLayerId) return;
    const layer = this.pointsLayers[this.editingLayerId] ?? this.linesLayers[this.editingLayerId];
    if (!layer) throw new Error(`layer with id ${this.editingLayerId} not found`);

    if (layer instanceof L.Marker) {
      this.loader.startLoadingForMarker(layer);
    }

    if (layer instanceof L.Polyline) {
      this.loader.startLoadingForPolyline(layer);
    }
  }

  stopLoadingForCurrent() {
    if (!this.editingLayerId) return;
    const layer = this.pointsLayers[this.editingLayerId] ?? this.linesLayers[this.editingLayerId];
    if (!layer) throw new Error(`layer with id ${this.editingLayerId} not found`);

    if (layer instanceof L.Marker) {
      this.loader.stopLoadingForMarker(layer);
    }

    if (layer instanceof L.Polyline) {
      this.loader.stopLoadingForPolyline(layer);
    }
  }

  removeObjectById(id: IRouteObject['id']) {
    const layer = this.pointsLayers[id] ?? this.linesLayers[id];
    if (!layer) throw new Error(`layer with id ${id} not found (removeObjectById)`);

    if (id === this.editingLayerId) {
      this.cancelEdit(id);
      this.setCurrentId(null);
    }

    this.map.removeLayer(layer);
    layer.remove();
  }
}

let leafletMapManagerInstance: LeafletMapManager | null = null;

export const setLeafletMapManager = (
  map: L.Map,
  onAddCallback: (e: L.Layer, cb: (e: IRouteObject) => void, name?: string) => void,
  onEditStarted: (id: IRouteObject['id'], e: L.Layer) => void,
  onSelectRouteObject: (id?: IRouteObject['id'] | null, e?: L.Layer) => void,
  onHotChange: (
    coordinates: CoordsWithOptionalEle[],
    activeLayerId: IRouteObject['id'] | null,
  ) => void,
  addStartCallback: () => void,
) => {
  leafletMapManagerInstance = new LeafletMapManager(
    map,
    onAddCallback,
    onEditStarted,
    onSelectRouteObject,
    onHotChange,
    addStartCallback,
  );
};
export const getLeafletMapManager = () => {
  if (!leafletMapManagerInstance) throw new Error('leafletMapManagetInstance is not set');
  return leafletMapManagerInstance;
};
