import React from 'react';

import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';

import { clearRoute } from '../../../@services/routes.service';

interface IClearRouteProps {
  onConfirm: () => void;
  id: number;
}

const ClearRouteModal: React.FC<IClearRouteProps> = ({ id, onConfirm }) => {
  const [markers, setIsmarkers] = React.useState(true);
  const [lines, setIslines] = React.useState(true);
  const [access, setIsaccess] = React.useState(true);

  const [isLoading, setIsLoading] = React.useState(false);

  const handleSubmit = async () => {
    try {
      setIsLoading(true);
      await clearRoute(id, { markers, lines, access });
      onConfirm();
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <section>
      <p>Выберите элементы которые нужно очистить</p>
      <PohCheckbox
        label="Удалить все маркеры"
        checked={markers}
        onChange={setIsmarkers}
        disabled={isLoading}
      />
      <PohCheckbox
        label="Удалить все пути"
        checked={lines}
        onChange={setIslines}
        disabled={isLoading}
      />
      <PohCheckbox
        label="Сбросить права доступа"
        checked={access}
        onChange={setIsaccess}
        disabled={isLoading}
      />

      <footer className="p-3 text-end">
        <PohButton variant={ButtonVariant.Primary} disabled={isLoading} onClick={handleSubmit}>
          Очистить
        </PohButton>
      </footer>
    </section>
  );
};

export default ClearRouteModal;
