import { ActionReducerMapBuilder, createAsyncThunk } from '@reduxjs/toolkit';
import * as L from 'leaflet';

import { formatDistance } from '@helpers/formatHelper';
import { getDistanceByCoordsInMeters } from '@helpers/gpsHelper';

import { RouteState, setCurrentRouteObject } from './route.slice';
import { RoutesState } from './store';
import {
  DEFAULT_LINE_COLOR,
  DEFAULT_LINE_OPACITY,
  DEFAULT_LINE_WEIGHT,
} from '../@const/routeObjects.const';
import { getCoordsFromLatLng, getMarkerStyles } from '../@helpers/leaflet.helper';
import { getLeafletMapManager } from '../@managers/leafletMap.manager';
import {
  addRouteLineAsync,
  addRoutePointAsync,
  deleteRouteObjectAsync,
  enrichAltitudesIfNecessary,
  getBaseRouteDataAsync,
  getMapTypesAsync,
  getPointInfoAsync,
  getRouteObjectsAsync,
  updateRouteLineAsync,
  updateRoutePointAsync,
} from '../@services/routes.service';
import {
  IBaseRouteObject,
  IBaseRouteObjectLine,
  IBaseRouteObjectPoint,
  IRouteObject,
} from '../@types/routes.types';

export const getRouteBaseData = createAsyncThunk('route/baseData', async (id_route: number) => {
  const { routeData } = await getBaseRouteDataAsync(id_route);
  const mapTypes = await getMapTypesAsync();

  return { routeData, mapTypes };
});

function invertHex(hex: string) {
  return (Number(`0x1${hex}`) ^ 0xffffff).toString(16).substr(1).toUpperCase();
}

export const getRouteObjectsData = createAsyncThunk(
  'route/routeObjects',
  async (id_route: number) => {
    const data = await getRouteObjectsAsync(id_route);

    return data;
  },
);

export const addRouteObject = createAsyncThunk(
  'route/routeObjectsAdd',
  async (
    {
      layer,
      cb,
      name,
      id_obstacle,
    }: {
      layer: L.Layer;
      cb: (ro: IRouteObject) => void;
      name?: string;
      id_obstacle?: null | number;
    },
    thunkApi,
  ) => {
    const { route } = thunkApi.getState() as RoutesState;
    if (!route.routeInfo) throw new Error('Has no route');

    const id_route = route.routeInfo.id;

    const manager = getLeafletMapManager();
    let newRo: IRouteObject | null = null;

    if (layer instanceof L.Marker) {
      const coords = getCoordsFromLatLng(layer.getLatLng());
      const [coordsWithEle] = await enrichAltitudesIfNecessary([coords]);
      const pointName = name || (await getPointInfoAsync(coordsWithEle)).name;
      newRo = await addRoutePointAsync(
        id_route,
        coordsWithEle,
        pointName || `Точка ${coordsWithEle[2] || coordsWithEle}`,
        getMarkerStyles(layer).color,
        id_obstacle,
      );
    }

    if (layer instanceof L.Polyline) {
      const latLngs = layer.getLatLngs() as L.LatLng[];
      const coords = latLngs.map(getCoordsFromLatLng);

      let lineName = name;
      if (!lineName) {
        const firstPointInfo = await getPointInfoAsync(coords[0]);
        const lastPointInfo = await getPointInfoAsync(coords[coords.length - 1]);
        lineName = [firstPointInfo.name, lastPointInfo.name].filter(Boolean).join(' — ');
      }

      const coordsWithEle = await enrichAltitudesIfNecessary(coords);
      newRo = await addRouteLineAsync(id_route, coordsWithEle, {
        name: lineName || `Путь ${formatDistance(getDistanceByCoordsInMeters(coords))}`,
        color: layer.options.color ?? DEFAULT_LINE_COLOR,
        opacity_pct: layer.options.opacity ? layer.options.opacity * 100 : DEFAULT_LINE_OPACITY,
        width: layer.options.weight ?? DEFAULT_LINE_WEIGHT,
        distance: getDistanceByCoordsInMeters(coords),
      });
    }

    if (!newRo) throw new Error('Не удалось добавить объект');

    cb(newRo);
    manager.addRouteObject(newRo);
    return newRo;
  },
);

export const updateRoutePoint = createAsyncThunk(
  'route/routePointUpdate',
  async (
    {
      point,
      hasCoordinatesChanges,
    }: { point: IBaseRouteObjectPoint; hasCoordinatesChanges: boolean },
    thunkApi,
  ) => {
    const { route } = thunkApi.getState() as RoutesState;
    if (!route.routeInfo) throw new Error('Has no route');

    const additional: { coordinates?: [number, number] | [number, number, number] } = {};

    if (hasCoordinatesChanges) {
      const layer = getLeafletMapManager().getPointById(point.id);

      if (!layer) throw new Error('Has no point layer');

      const coords = getCoordsFromLatLng(layer.getLatLng());
      const [coordsWithEle] = await enrichAltitudesIfNecessary([coords]);

      additional.coordinates = coordsWithEle;
    }

    return await updateRoutePointAsync(route.routeInfo.id, { ...point, ...additional });
  },
);

export const updateRouteLine = createAsyncThunk(
  'route/routeLineUpdate',
  async (
    {
      line,
      hasCoordinatesChanges,
      dividePoint,
      operation,
    }: {
      line: IBaseRouteObjectLine;
      hasCoordinatesChanges: boolean;
      dividePoint?: [number, number, number?];
      operation?: 'deleteFromStart' | 'deleteToEnd';
    },
    thunkApi,
  ) => {
    const { route } = thunkApi.getState() as RoutesState;

    if (!route.routeInfo) throw new Error('Has no route');

    // console.log({ line, hasCoordinatesChanges });
    const manager = getLeafletMapManager();
    let addedRouteObject: IRouteObject | null = null;

    const additional: {
      points?: Array<[number, number, number] | [number, number]>;
      distance?: number;
    } = {};

    if (hasCoordinatesChanges) {
      const layer = getLeafletMapManager().getLineById(line.id);
      if (!layer) throw new Error('Has no line layer');
      const latLngs = layer.getLatLngs() as L.LatLng[];
      const coords = latLngs.map(getCoordsFromLatLng);
      const coordsWithEle = await enrichAltitudesIfNecessary(coords);
      additional.points = coordsWithEle;
      additional.distance = getDistanceByCoordsInMeters(coords);
    }

    if (dividePoint) {
      const index = line.points.findIndex(
        (p) => p[0] === dividePoint[0] && p[1] === dividePoint[1],
      );
      if (index) {
        const currentPoints = additional.points ?? line.points;
        const points1 = operation
          ? operation === 'deleteFromStart'
            ? currentPoints.slice(index)
            : currentPoints.slice(0, index + 1)
          : currentPoints.slice(0, index + 1);
        const points2 = currentPoints.slice(index);

        additional.points = points1;
        additional.distance = getDistanceByCoordsInMeters(points1);

        const layer = getLeafletMapManager().getLineById(line.id);
        layer?.setLatLngs(points1);

        const id_route = route.routeInfo.id;

        if (!operation) {
          const distance2 = getDistanceByCoordsInMeters(points2);
          addedRouteObject = await addRouteLineAsync(id_route, points2, {
            name: '* ' + line.name,
            color: line.color ? '#' + invertHex(line.color.substr(1)) : DEFAULT_LINE_COLOR,
            opacity_pct: line.opacity ? line.opacity : DEFAULT_LINE_OPACITY,
            width: line.width ?? DEFAULT_LINE_WEIGHT,
            distance: distance2,
          });

          manager.addRouteObject(addedRouteObject);
        }
      } else {
        console.warn('Index not found for', { dividePoint });
      }
    }

    const updatedRouteObject = await updateRouteLineAsync(route.routeInfo.id, {
      ...line,
      ...additional,
    });

    if (addedRouteObject) {
      setTimeout(() => {
        if (addedRouteObject) {
          thunkApi.dispatch(setCurrentRouteObject(addedRouteObject));
          manager.startEdit(addedRouteObject.id);
        }
      });
    }
    if (operation) {
      setTimeout(() => {
        if (addedRouteObject) {
          thunkApi.dispatch(setCurrentRouteObject(addedRouteObject));
          manager.startEdit(addedRouteObject.id);
        }
      });
    }

    return {
      updatedRouteObject,
      addedRouteObject,
    };
  },
);

export const deleteRouteObject = createAsyncThunk(
  'route/deleteRouteObjects',
  async (id: IBaseRouteObject['id']) => {
    await deleteRouteObjectAsync(id);
  },
);

export const routeThunks = (builder: ActionReducerMapBuilder<RouteState>) => {
  // Base Route info
  builder.addCase(getRouteBaseData.fulfilled, (state, action) => {
    state.routeInfo = action.payload.routeData;
    state.mapTypes = action.payload.mapTypes;
    state.currentMapType =
      action.payload.mapTypes.find((t) => t.id === action.payload.routeData.id_type) ?? null;
    state.isBaseInfoLoading = false;
  });
  builder.addCase(getRouteBaseData.pending, (state) => {
    state.baseInfoError = undefined;
    state.isBaseInfoLoading = true;
  });
  builder.addCase(getRouteBaseData.rejected, (state, action) => {
    state.isBaseInfoLoading = false;
    state.baseInfoError = new Error(action.error.message);
  });

  // Route objects
  builder.addCase(getRouteObjectsData.fulfilled, (state, action) => {
    const routeObjects = action.payload;
    state.routeObjects = routeObjects;

    const manager = getLeafletMapManager();

    routeObjects.forEach(manager.addRouteObject);

    state.isRouteObjectsLoading = false;
  });
  builder.addCase(getRouteObjectsData.pending, (state) => {
    state.routeObjectsError = undefined;
    state.isRouteObjectsLoading = false;
  });
  builder.addCase(getRouteObjectsData.rejected, (state, action) => {
    state.isRouteObjectsLoading = false;
    state.routeObjectsError = new Error(action.error.message);
  });
  // NEW Route object
  builder.addCase(addRouteObject.fulfilled, (state, action) => {
    const newRouteObject = action.payload;
    console.info('addRouteObject.fulfilled', { newRouteObject });
    state.routeObjects = [...state.routeObjects, newRouteObject];
  });
  builder.addCase(addRouteObject.pending, () => {
    // state.routeObjectsError = undefined;
    // state.isRouteObjectsLoading = false;
  });
  builder.addCase(addRouteObject.rejected, () => {
    // state.isRouteObjectsLoading = false;
    // state.routeObjectsError = new Error(action.error.message);
  });

  // UPDATE Route POINT info
  builder.addCase(updateRoutePoint.fulfilled, (state, action) => {
    const updatedRouteObject = action.payload;
    state.routeObjects = state.routeObjects.map((ro) =>
      updatedRouteObject.id === ro.id ? updatedRouteObject : ro,
    );
  });
  builder.addCase(updateRoutePoint.pending, () => {
    // state.routeObjectsErPoupdateRoutePointInfo
    // state.isRouteObjectsPoupdateRoutePointInfo
  });
  builder.addCase(updateRoutePoint.rejected, (_, action) => {
    console.error('UPRouteObject.rejected', action.error);
    // state.isRouteObjectsLoading = false;
    // state.routeObjectsError = new Error(action.error.message);
  });

  // UPDATE Route LINE info
  builder.addCase(
    updateRouteLine.fulfilled,
    (state, { payload: { updatedRouteObject, addedRouteObject } }) => {
      const up = state.routeObjects.map((ro) =>
        updatedRouteObject.id === ro.id ? updatedRouteObject : ro,
      );

      if (addedRouteObject) {
        up.push(addedRouteObject);
      }
      if (state.currentRouteObject?.id === updatedRouteObject.id) {
        state.currentRouteObject = updatedRouteObject;
      }

      if (state.activeRouteObject?.id === updatedRouteObject.id) {
        state.activeRouteObject = updatedRouteObject;
      }
      state.routeObjects = up;
    },
  );
  builder.addCase(updateRouteLine.pending, () => {
    // state.routeObjectsError = undefined;
    // state.isRouteObjectsLoading = false;
  });
  builder.addCase(updateRouteLine.rejected, (_, action) => {
    console.error('UPRouteObject.rejected', action.error);
    // state.isRouteObjectsLoading = false;
    // state.routeObjectsError = new Error(action.error.message);
  });

  //deleteRouteObject
  builder.addCase(deleteRouteObject.fulfilled, (state, action) => {
    state.routeObjects = state.routeObjects.filter((ro) => action.meta.arg !== ro.id);
  });
};
