import React from 'react';

import { LayersControl, TileLayer } from 'react-leaflet';

import { useRoutesSelector } from '../../../../@store/hooks';

const MapTypesControl = () => {
  const { currentMapType, mapTypes } = useRoutesSelector((state) => state.route);

  return (
    <LayersControl position="bottomright">
      {mapTypes.map((type) => {
        return (
          <LayersControl.BaseLayer
            key={type.id}
            checked={currentMapType?.id === type.id}
            name={type.name}
          >
            <TileLayer
              attribution={type.name}
              url={type.tileUrlTmpl}
              minZoom={type.minZoom}
              maxZoom={type.maxZoom}
              id={type.id.toString()}
            />
          </LayersControl.BaseLayer>
        );
      })}
    </LayersControl>
  );
};

export default MapTypesControl;
