import * as L from 'leaflet';

import styles from './styles.module.less';

function pointOnDistance(p1: L.LatLng, p2: L.LatLng, dist: number): L.LatLng {
  const factor = dist / p1.distanceTo(p2);
  const lat = p1.lat + (p2.lat - p1.lat) * factor;
  const lng = p1.lng + (p2.lng - p1.lng) * factor;
  return L.latLng(lat, lng);
}

function formatDistance(distance: number): string {
  return (distance / 1000).toFixed(1).replace('.0', '') + '\u2009km';
}

function getCSSForSegment(a: L.LatLng, b: L.LatLng, forEnd = false) {
  const p1 = L.CRS.EPSG3857.project(a);
  const p2 = L.CRS.EPSG3857.project(b);
  const dx = p2.x - p1.x;
  const dy = p1.y - p2.y;
  const len = Math.sqrt(dx * dx + dy * dy);
  const sin = dy / len;
  const cos = dx / len;

  const parts = [];
  if (sin > 0) {
    parts.push(`transform: matrix(${[sin, -cos, cos, sin, 0, 0].join(',')})`);
    // forEnd && parts.push(`rotate: ${cos>0 ? '' : '-'}45deg`);
  } else {
    parts.push(`transform: matrix(${[-sin, cos, -cos, -sin, 0, 0].join(',')})`);
    // forEnd && parts.push(`rotate: ${cos>0 ? '-' : ''}45deg`);
  }

  if (forEnd) {
    sin <= 0 && cos >= 0 && parts.push(`rotate: -90deg`); // 12 - 3 часов
    sin >= 0 && cos >= 0 && parts.push(`rotate: 90deg`); // 3 - 6 часов
    sin >= 0 && cos <= 0 && parts.push(`rotate: -90deg; right: 0`); // 6 - 9 часов
    sin <= 0 && cos <= 0 && parts.push(`rotate: 90deg; right: 0`); // 9 -12  часов
  }

  return parts.join('; ');
}

const zoomStepsMap: Record<number, number> = {
  18: 0.2,
  17: 0.2,
  16: 0.2,
  15: 0.5,
  14: 0.5,
  13: 1,
  12: 2,
  11: 5,
  10: 10,
  9: 20,
  8: 50,
  7: 50,
  6: 100,
  5: 100,
};

interface IXneekPolylineTicksOptions {}

export class XneekPolylineTicks {
  private readonly map: L.Map;
  private readonly options: IXneekPolylineTicksOptions = {};

  private measuresGroup = L.layerGroup();
  private measuresPotentialGroup = L.layerGroup();

  totalDistance: number = 0;

  private step = 0;
  private color = 'black';

  private points: L.LatLng[] = [];
  private startDistance: number = 0;

  private mapBounds: L.LatLngBounds | null;

  private lastTick = 0;
  private lastPoint = 0;

  private needLastPoint = true;

  private redrawDebounce: ReturnType<typeof setTimeout> | null = null;

  constructor(map: L.Map, options: Partial<IXneekPolylineTicksOptions> = {}) {
    this.mapBounds = null;
    this.map = map;
    this.options = {
      ...this.options,
      ...options,
    };

    if (!Number.isFinite(this.map.getZoom())) return;
    this.mapBounds = this.map.getBounds();
    this.step = (zoomStepsMap[this.map.getZoom()] || 100) * 1000;
    this.log('constructor', { options, step: this.step });
  }

  log(...args: any[]) {
    console.info('xneek ticks', ...args);
  }

  handleZoomEnd = () => {
    this.log('handleZoomEnd');
    this.step = (zoomStepsMap[this.map.getZoom()] || 100) * 1000;
    this.mapBounds = this.map.getBounds();
    this.redrawMeasureTicks();
  };

  init(layer: L.LayerGroup) {
    this.log('init', { layer });
    this.measuresGroup = layer;
    this.measuresGroup.setZIndex(-500);
    this.measuresPotentialGroup.addTo(this.map);
    this.map.on('zoomend', this.handleZoomEnd);
  }

  destroy() {
    this.log('destroy');
    this.map.removeLayer(this.measuresPotentialGroup);
    this.measuresGroup.clearLayers();
    this.measuresPotentialGroup.remove();
    this.map.off('zoomend', this.handleZoomEnd);
  }

  setStartDistance(startDistanceInMeters = 0) {
    this.log('setStartDistance', startDistanceInMeters);
    this.startDistance = startDistanceInMeters;
  }

  setColor(color = 'black') {
    this.log('setColor', color);
    this.color = color;
  }

  drawMeasureTicks(points: L.LatLng[]) {
    this.log('drawMeasureTicks', points);
    if (points.length == 1) {
      this.log('drawMeasureTicks break because 1 item');
      return;
    }
    this.points = points;
    if (points.length < 1000) {
      this.log('drawMeasureTicks break because points.length < 1000');
      this.redrawMeasureTicks('drawMeasureTicks, < 1000');
      return;
    }

    this.measuresGroup.clearLayers();

    this.redrawDebounce && clearTimeout(this.redrawDebounce);
    this.redrawDebounce = setTimeout(() => {
      this.redrawMeasureTicks('drawMeasureTicks');
    }, 100);
  }

  redrawMeasureTicks(reason = '') {
    this.log('redrawMeasureTicks', reason);
    //console.time('drawMeasures')
    this.measuresGroup.clearLayers();

    const points = this.points; //.filter((p) => this.mapBounds.contains(p));

    //console.info('Filtred points', points, '/', this.points)

    let dist = 0;

    this.lastTick = this.startDistance;
    this.lastPoint = this.startDistance;

    points.forEach((point, i, arr) => {
      if (i === 0) return;
      const prevPoint = arr[i - 1];
      const curDist = point.distanceTo(prevPoint);
      const nextPoint = this.lastPoint + curDist;

      if (nextPoint >= this.lastTick + this.step && this.lastTick + this.step > 0) {
        while (this.lastTick + this.step <= nextPoint) {
          this.lastTick += this.step;
          this.log('redrawMeasureTicks while');
          const coords = pointOnDistance(prevPoint, point, this.lastTick - this.lastPoint);
          if (this.mapBounds && !this.mapBounds.contains(coords)) continue; // если точка за пределми текущей области видимости, не рисуем ее
          const marker = L.marker(coords, {
            draggable: false,
            interactive: false,
            icon: L.divIcon({
              html: `<small
              class="${styles.measureMarker}"
              style="color: ${this.color}; ${getCSSForSegment(point, prevPoint)}">
              ${formatDistance(this.lastTick)}
            </small>`,
              className: styles.measureMarkerWrapper,
            }),
          });
          this.measuresGroup.addLayer(marker);
        }
      }

      this.lastPoint = nextPoint;

      dist += curDist;
    });

    if (this.needLastPoint) {
      const marker = L.marker(points[points.length - 1], {
        draggable: false,
        interactive: false,
        icon: L.divIcon({
          html: `<small
              class="${[styles.measureMarker, styles.lastPoint].join(' ')}"
              style="color: ${this.color}; ${getCSSForSegment(points[points.length - 2], points[points.length - 1])}">
              ${formatDistance(this.startDistance + dist)}
            </small>`,
          className: styles.measureMarkerWrapper,
        }),
      });

      this.measuresGroup.addLayer(marker);

      marker.setZIndexOffset(-500);
    }

    this.totalDistance = dist;
    // console.timeEnd('drawMeasures')
  }

  drawPotential(point: L.LatLng, prevPoint: L.LatLng) {
    this.log('drawPotential', { point: point.toString(), prevPoint: prevPoint.toString() });
    this.measuresPotentialGroup.clearLayers();

    let lastTickDistance = this.lastTick || this.startDistance;
    const lastPointDistance = this.lastPoint || this.startDistance;

    this.log('drawPotential', { lastTickDistance, lastPointDistance, step: this.step });

    const curDist = point.distanceTo(prevPoint);
    this.log('drawPotential curDist =', curDist);
    if (lastTickDistance + this.step === 0) {
      this.log('drawPotential skip because ZERO');
      return;
    }

    const nextPointDist = lastPointDistance + curDist;

    if (nextPointDist >= lastTickDistance + this.step) {
      while (lastTickDistance + this.step <= nextPointDist && lastTickDistance + this.step > 0) {
        lastTickDistance += this.step;
        this.log('while', lastTickDistance);
        const coords = pointOnDistance(prevPoint, point, lastTickDistance - lastPointDistance);
        const marker = L.marker(coords, {
          draggable: false,
          interactive: false,
          icon: L.divIcon({
            html: `<small
              class="${styles.measureMarker}"
              style="color: ${this.color}; ${getCSSForSegment(point, prevPoint)}">
              ${formatDistance(lastTickDistance)}
            </small>`,
            className: styles.measureMarkerWrapper,
          }),
        });
        marker.setZIndexOffset(-500);
        this.measuresPotentialGroup.addLayer(marker);
      }
    }

    if (this.needLastPoint) {
      const marker = L.marker(point, {
        draggable: false,
        interactive: false,
        icon: L.divIcon({
          html: `<small
              class="${styles.measurePotential}"
              style="color: ${this.color}; ${getCSSForSegment(prevPoint, point, true)};" data-content="${formatDistance(nextPointDist)}">

            </small>`,
          className: styles.measureMarkerPotentialWrapper,
        }),
      });

      this.measuresPotentialGroup.addLayer(marker);

      marker.setZIndexOffset(-500);
    }
  }

  clearPotential() {
    this.measuresPotentialGroup.clearLayers();
  }

  setNeedLatPoint(value = true) {
    this.needLastPoint = value;
  }

  public get distance(): number {
    return this.totalDistance;
  }
}
