import React, { HTMLAttributes } from 'react';

import clsx from 'clsx';
interface IRoutesEditorSidebarHeaderBadgeProps extends HTMLAttributes<HTMLSpanElement> {
  active: boolean;
}
const RoutesEditorSidebarHeaderBadge: React.FC<IRoutesEditorSidebarHeaderBadgeProps> = ({
  active,
  className,
  children,
}) => {
  return (
    <sup
      className={clsx(
        'position-absolute',
        className,
        active ? 'bg-info text-light' : 'bg-light text-muted',
      )}
      style={{
        left: '80%',
        bottom: '70%',
        padding: 3,
        borderRadius: 50,
        fontSize: 8,
        lineHeight: '5px',
      }}
    >
      <small>{children}</small>
    </sup>
  );
};

export default RoutesEditorSidebarHeaderBadge;
