import React from 'react';

import * as L from 'leaflet';

import { getDefaultTileLayer, getMap } from '@helpers/leafletHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import PohLoader, { LoaderVariant } from '@ui-kit/Loader';

import { getDivIcon } from '../../../@helpers/leaflet.helper';
import { IPointAround, searchAroundPoint } from '../../../@services/routes.service';

interface IPointsAroundModalProps {
  lat: number;
  lon: number;
  radius: number;
  onChange: (pointWithName: IPointAround) => void;
}

const PointsAroundModal: React.FC<IPointsAroundModalProps> = ({
  onChange,
  radius: defaultRadius,
  lat,
  lon,
}) => {
  const [radius, setRadius] = React.useState(defaultRadius);
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();
  const [results, setResults] = React.useState<IPointAround[]>([]);
  const [selected, setSelected] = React.useState<IPointAround | null>(null);

  const ref = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);
  const layerGroupRef = React.useRef<L.FeatureGroup>(null);
  const to = React.useRef<ReturnType<typeof setTimeout>>(null);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      setErr(undefined);
      layerGroupRef.current && layerGroupRef.current.clearLayers();
      const res = await searchAroundPoint(lat, lon, radius);
      setResults(res);
    } catch (e) {
      setErr(e as Error);
      setResults([]);
    } finally {
      setIsLoading(false);
    }
  }, [radius, lat, lon]);

  React.useEffect(() => {
    load();
  }, [lat, lon]);

  React.useEffect(() => {
    if (!ref.current) return;
    if (!mapRef.current) {
      mapRef.current = getMap(ref.current as HTMLElement);
      getDefaultTileLayer().addTo(mapRef.current);
      layerGroupRef.current = L.featureGroup().addTo(mapRef.current);
    }

    layerGroupRef.current && layerGroupRef.current.clearLayers();

    results.forEach((r) => {
      if (!layerGroupRef.current) return;
      const layer = new L.Marker([r.lat, r.lon], { icon: getDivIcon() });
      layer.bindTooltip(r.name ?? '');
      layer.on('click', () => {
        setSelected(r);
      });
      layer.addTo(layerGroupRef.current);
    });

    const bounds = layerGroupRef.current?.getBounds();
    if (bounds && bounds.isValid()) mapRef.current.fitBounds(bounds);
  }, [results]);

  return (
    <section style={{ width: 800 }}>
      <PohRow>
        <PohCol sm={9}>
          <div ref={ref} style={{ height: 360 }}></div>
        </PohCol>
        <PohCol sm={3}>
          <div style={{ overflowY: 'auto', maxHeight: 360 }}>
            {err && <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>}
            {isLoading ? (
              <PohLoader variant={LoaderVariant.Dark} />
            ) : (
              <PohList
                data={results.map((res) => {
                  return {
                    key: res.id,
                    action: true,
                    active: res.id === selected?.id,
                    onClick: () => {
                      setSelected(res);
                      mapRef.current?.panTo(new L.LatLng(res.lat, res.lon));
                    },
                    children: res.name,
                    className: 'text-truncate',
                  };
                })}
              />
            )}
          </div>
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol xs={9}>
          <PohInput
            type={InputTypes.number}
            value={radius.toString()}
            label="Радиус поиска (м)"
            step={100}
            min="100"
            max="10000"
            onChange={(v) => {
              setRadius(+v);
              to.current && clearTimeout(to.current);
              to.current = setTimeout(() => load(), 1000);
            }}
          />
        </PohCol>
        <PohCol xs={3} className="text-end text-muted"></PohCol>
      </PohRow>

      <footer className="py-3 text-end">
        <PohButton
          variant={ButtonVariant.Primary}
          disabled={!selected}
          onClick={() => selected && onChange(selected)}
        >
          Использовать точку
        </PohButton>
      </footer>
    </section>
  );
};

export default PointsAroundModal;
